examples.content:
UPDATE Mark SET Score = 85 WHERE MarkID = 2;
-- Wei's Maths mark (MarkID 2) changes from 65 to 85; the other four Mark rows are unaffected.

DELETE FROM Mark WHERE StudentID = 4 AND Subject = 'Maths';
-- Fatima's Maths mark (MarkID 5) is removed entirely; the Student table is unaffected,
-- since DELETE removes rows from Mark only, not from the table it names.
